"""Italiano — virtù (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Secondo un hadith riportato dall'imam al-Bukhari, che cosa deve fare con le sue parole chi crede in Allah e nell'Ultimo Giorno?", ["Dire il bene o tacere", "Parlare a voce alta", "Non parlare mai", "Ripetere le dicerie"], "Il Profeta ﷺ disse: «Chi crede in Allah e nell'Ultimo Giorno dica il bene o taccia.»"),
"virtues_002": ("Secondo lo stesso hadith, chi altro deve onorare il credente, oltre al suo ospite?", ["Il suo vicino", "Il suo mercante", "Il suo rivale", "Uno sconosciuto"], "L'hadith prosegue: «…e chi crede in Allah e nell'Ultimo Giorno onori il suo vicino.»"),
"virtues_003": ("Lo stesso hadith menziona anche di onorare chi, quando arriva a casa propria?", ["L'ospite", "Solo il vicino", "Il mercante", "Un viaggiatore sconosciuto e lontano"], "L'hadith completo dice: «…chi crede in Allah e nell'Ultimo Giorno onori il suo ospite.»"),
"virtues_004": ("Secondo un hadith autentico, la fede di un credente non è completa finché non ama per il fratello ciò che ama per…", ["se stesso", "la sua ricchezza", "solo la sua famiglia", "il suo paese"], "Il Profeta ﷺ disse: «Nessuno di voi crede veramente finché non ama per il fratello ciò che ama per se stesso.»"),
"virtues_005": ("Secondo un hadith autentico, il vero musulmano è colui dalla cui lingua e dalla cui ___ gli altri sono al sicuro.", ["mano", "ricchezza", "sguardo", "voce"], "Il Profeta ﷺ disse: «Il musulmano è colui dalla cui lingua e dalla cui mano gli altri musulmani sono al sicuro.»"),
"virtues_006": ("Il Corano ordina la bontà verso i genitori e proibisce di dire loro persino quale parola di fastidio?", ["«Uff» (un suono di impazienza)", "«No»", "«Basta»", "«Aspetta»"], "Il Corano chiede la massima bontà verso i genitori, proibendo persino la più lieve parola di disprezzo."),
"virtues_007": ("A che cosa il Corano paragona la maldicenza (parlare male di un assente)?", ["A mangiare la carne del proprio fratello morto", "A bere acqua salata", "A camminare nel buio", "A seminare nella sabbia"], "«Qualcuno di voi vorrebbe mangiare la carne del proprio fratello morto? Ne avreste orrore!»: tanto è brutta la maldicenza."),
"virtues_008": ("Come descrive il Corano il rapporto tra i credenti?", ["Sono fratelli", "Sono concorrenti", "Sono estranei", "Sono soci in affari"], "«I credenti non sono che fratelli, riconciliate dunque i vostri due fratelli.»"),
"virtues_009": ("Che cosa dice il Corano sul deridere gli altri?", ["È proibito: i derisi potrebbero essere migliori di chi deride", "È permesso tra amici", "È permesso se è divertente", "È riservato ai poeti"], "«Che un popolo non derida un altro popolo: forse sono migliori di loro.»"),
"virtues_010": ("Secondo il Corano, che cosa promette Allah a chi è riconoscente?", ["Gli darà certamente di più", "Una lunga vita", "Ricchezza immediata", "Un viaggio"], "«Se sarete riconoscenti, vi accrescerò certamente.»"),
"virtues_011": ("Secondo il Corano, come verrà data la ricompensa ai pazienti (sabirun)?", ["In pieno, senza misura", "Tutta in una volta", "Dopo quaranta giorni", "Secondo la loro ricchezza"], "«Ai pazienti sarà data la loro ricompensa in pieno, senza conto.»"),
"virtues_012": ("«Mangiate e bevete, ma…»: come continua questo versetto?", ["Non sprecate", "Non condividete", "Non parlate", "Non uscite"], "«Mangiate e bevete, ma senza eccessi: Allah non ama gli sprecatori.»"),
"virtues_013": ("Quale versetto, spesso recitato nel sermone del venerdì, riassume ciò che Allah ordina?", ["«Allah ordina la giustizia e il bene»", "«Allah ordina il commercio»", "«Allah ordina il viaggio»", "«Allah ordina il silenzio»"], "«Allah ordina la giustizia, il bene e la generosità verso i parenti…»: recitato ogni venerdì."),
"virtues_014": ("Contro chi si apre la sura Al-Mutaffifin con «Guai…»?", ["Coloro che frodano nella misura e nel peso", "Coloro che dormono", "Coloro che viaggiano", "Coloro che tacciono"], "«Guai ai frodatori: che pretendono la misura piena quando ricevono, ma danno di meno quando misurano per gli altri.»"),
"virtues_015": ("Secondo la sura Ad-Duha, come vanno trattati l'orfano e chi chiede?", ["Né oppressi né respinti", "Ignorati", "Mandati da altri", "Ascoltati più tardi"], "«Quanto all'orfano, non opprimerlo; e quanto a chi chiede, non respingerlo.»"),
"virtues_016": ("Come il Corano ordina di parlare alle persone?", ["Con parole buone", "A voce molto bassa", "Il meno possibile", "Solo ai parenti"], "«…e parlate alla gente con parole buone»: la parola gentile è essa stessa adorazione."),
"virtues_017": ("Nei suoi consigli al figlio, che cosa dice Luqman sul camminare e sull'orgoglio?", ["Non camminare sulla terra con arroganza", "Cammina sempre in fretta", "Cammina solo di notte", "Non camminare mai da solo"], "«Non voltare il viso dalla gente per orgoglio, e non camminare sulla terra con arroganza.»"),
"virtues_018": ("Secondo il primissimo hadith della raccolta di al-Bukhari, da che cosa sono giudicate le azioni?", ["Dalle intenzioni", "Dai risultati", "Dalle abitudini", "Dai testimoni"], "«Le azioni valgono secondo le intenzioni, e ognuno avrà solo ciò che ha inteso.»"),
"virtues_019": ("Secondo un hadith in al-Bukhari, dove conduce la veridicità (sidq)?", ["Alla rettitudine, e la rettitudine conduce al Paradiso", "Alla ricchezza", "Alla fama", "Alla forza"], "«La veridicità conduce alla rettitudine, e la rettitudine conduce al Paradiso; la menzogna conduce alla perversione, e la perversione conduce al Fuoco.»"),
"virtues_020": ("Secondo un hadith autentico, quali sono i tre segni dell'ipocrita?", ["Mente quando parla, non mantiene le promesse e tradisce la fiducia", "Dorme, mangia e parla troppo", "Viaggia, commercia e canta", "Prega poco, digiuna poco e legge poco"], "«I segni dell'ipocrita sono tre: quando parla mente, quando promette non mantiene, e quando gli si dà fiducia tradisce.»"),
"virtues_021": ("Un uomo chiese consiglio al Profeta ﷺ; che cosa gli ripeté più volte?", ["«Non arrabbiarti»", "«Viaggia molto»", "«Mangia poco»", "«Parla a voce alta»"], "L'uomo disse: «Consigliami.» Rispose: «Non arrabbiarti.» L'uomo chiese di nuovo, ed egli ripeté: «Non arrabbiarti.»"),
"virtues_022": ("Secondo il Profeta ﷺ, chi è veramente forte?", ["Chi si domina quando è in collera", "Chi vince nella lotta", "Chi porta i carichi più pesanti", "Chi corre più veloce"], "«Il forte non è chi vince gli altri nella lotta; il forte è chi si domina quando è in collera.»"),
"virtues_023": ("Secondo un hadith in al-Bukhari, il pudore (haya') è parte di che cosa?", ["Della fede", "Della debolezza", "Della ricchezza", "Della timidezza biasimevole"], "Vedendo un uomo rimproverare il fratello per il suo pudore, il Profeta ﷺ disse: «Lascialo, perché il pudore è parte della fede.»"),
"virtues_024": ("Che cosa disse il Profeta ﷺ a un uomo che si vantava di non aver mai baciato nessuno dei suoi dieci figli?", ["«Chi non mostra misericordia non riceverà misericordia»", "«Hai ragione»", "«I bambini non contano»", "«È una questione privata»"], "Il Profeta ﷺ baciava i suoi nipoti; ad Al-Aqra', che se ne stupiva, rispose: «Man la yarham la yurham.»"),
"virtues_025": ("Secondo un hadith in al-Bukhari, per quale azione un uomo fu perdonato?", ["Per aver dato da bere a un cane assetato", "Per aver costruito un pozzo", "Per aver piantato un albero", "Per aver scacciato un lupo"], "L'uomo scese in un pozzo, riempì la sua scarpa d'acqua e la diede a un cane che ansimava di sete; Allah lo perdonò."),
"virtues_026": ("Secondo un hadith autentico, perché una donna fu punita?", ["Per aver rinchiuso una gatta senza nutrirla né lasciarla cercare cibo", "Per aver venduto una gatta", "Per aver cacciato una gatta da casa sua", "Per aver adottato troppi gatti"], "«Una donna fu punita per una gatta che aveva rinchiuso finché morì: non la nutrì né la lasciò mangiare delle creature della terra.»"),
"virtues_027": ("Di chi disse il Profeta ﷺ che Jibril continuava a raccomandarglielo tanto che pensò lo avrebbe reso erede?", ["Il vicino", "L'ospite", "L'orfano", "Il viaggiatore"], "«Jibril ha continuato a raccomandarmi il vicino, tanto che ho pensato che lo avrebbe reso erede.»"),
"virtues_028": ("Secondo un hadith in al-Bukhari, quanti diritti ha un musulmano sul suo fratello musulmano?", ["Cinque", "Tre", "Sette", "Dieci"], "«Rispondere al saluto, visitare il malato, seguire il funerale, accettare l'invito e rispondere a chi starnutisce.»"),
"virtues_029": ("Alla domanda «Quale Islam è il migliore?», che cosa rispose il Profeta ﷺ?", ["Nutrire la gente e salutare chi conosci e chi non conosci", "Costruire moschee", "Viaggiare molto", "Parlare poco"], "«Nutrire gli altri, e dare il saluto di pace a chi conosci e a chi non conosci.»"),
"virtues_030": ("A che cosa il Profeta ﷺ paragona i credenti nel loro amore e sostegno reciproco?", ["A un solo corpo: se un membro soffre, tutto il corpo veglia con la febbre", "A una foresta", "A una carovana", "A un gregge"], "«I credenti, nel loro amore, misericordia e compassione reciproci, sono come un solo corpo.»"),
"virtues_031": ("Secondo il Profeta ﷺ, qual è «il più falso dei discorsi»?", ["Il sospetto (zann)", "La poesia", "Lo scherzo", "Il silenzio"], "«Guardatevi dal sospetto, perché il sospetto è il più falso dei discorsi.»"),
"virtues_032": ("Secondo un hadith autentico, per quanti giorni al massimo un musulmano può evitare il fratello?", ["Tre giorni", "Sette giorni", "Un mese", "Un anno"], "«Non è lecito a un uomo evitare il fratello per più di tre notti… e il migliore dei due è chi saluta per primo.»"),
"virtues_033": ("Secondo il Profeta ﷺ, qual è il valore di ogni buona azione, per quanto piccola?", ["È un'elemosina (sadaqa)", "Non conta", "Vale un dinar", "Sostituisce la preghiera"], "«Ogni buona azione è un'elemosina.»"),
"virtues_034": ("Secondo un hadith in Sahih Muslim, qual è il ramo più umile della fede?", ["Togliere dalla strada ciò che è nocivo", "Costruire una moschea", "Recitare un juz'", "Digiunare un giorno"], "«La fede ha settanta e più rami: il più alto è 'la ilaha illa Allah', il più basso è togliere dalla strada ciò che è nocivo; e il pudore è un ramo della fede.»"),
"virtues_035": ("Secondo un hadith in Sahih Muslim, la purezza (tahara) è…?", ["Metà della fede", "Un terzo della fede", "Un decimo della fede", "Senza rapporto con la fede"], "«La purezza è metà della fede, e 'al-hamdu li-Llah' riempie la bilancia.»"),
"virtues_036": ("Il Profeta ﷺ disse: «La religione è nasiha (consiglio sincero)»: verso chi?", ["Verso Allah, il Suo Libro, il Suo Messaggero, i governanti e tutti i musulmani", "Solo verso se stessi", "Verso i ricchi", "Verso gli sconosciuti"], "Chiesero: «Verso chi?» Disse: «Verso Allah, il Suo Libro, il Suo Messaggero, i governanti dei musulmani e la loro gente comune.»"),
"virtues_037": ("Secondo un hadith in Sahih Muslim, che cosa guarda Allah nei Suoi servi?", ["I loro cuori e le loro azioni", "Il loro aspetto", "La loro ricchezza", "Il loro numero"], "«Allah non guarda i vostri corpi né il vostro aspetto, ma guarda i vostri cuori e le vostre azioni.»"),
"virtues_038": ("Secondo un hadith in Sahih Muslim, che cosa fa Allah per chi solleva un credente da una difficoltà di questo mondo?", ["Lo solleva da una difficoltà nel Giorno della Resurrezione", "Lo rende ricco", "Gli concede una lunga vita", "Lo rende famoso"], "«Chi solleva un credente da una difficoltà di questo mondo, Allah lo solleverà da una difficoltà nel Giorno della Resurrezione.»"),
"virtues_039": ("Secondo il Profeta ﷺ, che cosa fa Allah per chi percorre una via in cerca di conoscenza?", ["Gli facilita una via verso il Paradiso", "Lo dispensa dalla preghiera", "Lo rende ricco", "Lo rende re"], "«Chi percorre una via in cerca di conoscenza, Allah gli facilita una via verso il Paradiso.»"),
"virtues_040": ("Secondo un hadith in al-Bukhari, chi è «il migliore di voi»?", ["Chi impara il Corano e lo insegna", "Chi parla meglio", "Chi possiede di più", "Chi viaggia di più"], "«Il migliore di voi è chi impara il Corano e lo insegna.»"),
"virtues_041": ("Come definì il Profeta ﷺ l'arroganza (kibr)?", ["Rifiutare la verità e disprezzare la gente", "Indossare bei vestiti", "Amare le belle scarpe", "Camminare in fretta"], "All'uomo che amava i bei vestiti disse: «Allah è bello e ama la bellezza. L'arroganza è rifiutare la verità e disprezzare la gente.»"),
"virtues_042": ("Secondo un hadith in al-Bukhari, quali due benedizioni molte persone non sanno sfruttare?", ["La salute e il tempo libero", "Il denaro e la fama", "La forza e la bellezza", "La famiglia e gli amici"], "«Ci sono due benedizioni in cui molte persone sono in perdita: la salute e il tempo libero.»"),
"virtues_043": ("Completa questo hadith: «Il credente non viene punto due volte…»", ["«…dalla stessa tana»", "«…dallo stesso scorpione»", "«…nello stesso giorno»", "«…dalla stessa ape»"], "«La yuldaghu al-mu'minu min juhrin wahidin marratayn»: il credente impara dai suoi errori."),
"virtues_044": ("A che cosa il Profeta ﷺ paragona il buon compagno, in contrasto con il fabbro?", ["Al venditore di muschio", "Al fornaio", "Al pastore", "Al mercante di stoffe"], "«Il buon compagno è come il portatore di muschio: te ne dà, o ne compri da lui, o ne senti il profumo; il cattivo è come il mantice del fabbro.»"),
"virtues_045": ("Secondo un hadith in al-Bukhari, di che cosa ognuno di noi è responsabile, «come un pastore»?", ["Di coloro che ci sono affidati", "Del tempo atmosferico", "Delle stelle", "Dei raccolti altrui"], "«Ognuno di voi è un pastore, e ognuno è responsabile del suo gregge»: il governante del suo popolo, l'uomo della sua famiglia, la donna della sua casa."),
"virtues_046": ("Secondo il Corano, che cosa accade se si respinge il male con ciò che è migliore?", ["Chi era nemico diventa come un amico caloroso", "Il male scompare dalla terra", "Si diventa ricchi", "Nulla cambia"], "«Respingi il male con ciò che è migliore, e colui tra cui e te c'era inimicizia diventerà come un amico caloroso» (41:34)."),
"virtues_047": ("Come rispondono «i servi del Misericordioso» agli ignoranti che li provocano, secondo la sura Al-Furqan?", ["Dicono: «Pace!»", "Rispondono con collera", "Li deridono", "Li colpiscono"], "«I servi del Misericordioso camminano umilmente sulla terra, e quando gli ignoranti si rivolgono a loro, dicono: Pace!» (25:63)."),
"virtues_048": ("Che cosa dice il Corano sul patto (una promessa, un impegno)?", ["«Mantenete il patto, perché del patto sarà chiesto conto»", "«Una promessa non vincola nessuno»", "«Promettete solo ai ricchi»", "«Non promettete mai»"], "«E mantenete il patto; in verità, del patto sarà chiesto conto» (17:34)."),
"virtues_049": ("Di chi dice il Corano che sono «i fratelli dei demoni»?", ["Gli sperperatori", "I viaggiatori", "I mercanti", "I poeti"], "«Gli sperperatori sono i fratelli dei demoni, e il Demonio è ingrato verso il suo Signore» (17:27)."),
"virtues_050": ("Quali sono le «due parole leggere sulla lingua, pesanti sulla bilancia e amate dal Misericordioso»?", ["«Subhana Allahi wa bi-hamdih, subhana Allahi al-'Azim»", "«Allahu akbar, al-hamdu li-Llah»", "«La ilaha illa Allah, Muhammad rasulu Allah»", "«Bismi Allah, ma sha'a Allah»"], "«Due parole leggere sulla lingua, pesanti sulla bilancia, amate dal Misericordioso: Gloria ad Allah e lode a Lui; gloria ad Allah l'Immenso.»"),
}
